// Explode each relevant AI result into one row per catalog item, mapped to the REAL
// catalog_lines columns, and decide DETERMINISTICALLY (no AI) whether each item is a
// new line or an update to an existing one. Extras -> extra (jsonb).
//
// Matching cascade, in order, against lines NOT yet sent to Hermes:
//   1. EAN        — digits only, leading zeros ignored (the same product arrives as
//                   "0093624872443" and as "093624872443")
//   2. catalogue number — punctuation/spacing ignored
// Identifiers ONLY: artist/title/format are never used to match, because the same
// artist + title + format is routinely several different SKUs. An item carrying
// neither an EAN nor a catalogue number therefore always becomes a new line, to be
// merged by hand. The catalogue-number tier fires only when EXACTLY ONE candidate
// matches, and never across a conflicting barcode: two lines sharing a catalogue
// number but carrying different EANs are different products. Anything ambiguous
// becomes a new line flagged for review rather than a guess.
//
// Lines already sent to Hermes are frozen — Hermes is insert-only, so an update
// cannot be pushed there. A follow-up for one of those leaves the data untouched and
// records a note instead of disappearing silently.

function toCatalogCode(ean) {
  if (ean === null || ean === undefined) return null;
  const s = String(ean).replace(/\D/g, '');
  if (!s) return null;
  const trimmed = s.slice(0, -1).replace(/^0+/, '');
  return trimmed || null;
}

// Hard guarantee (never trust the model): neither artist nor title may start
// with "THE". Strip a leading "THE " (case-insensitive) + surrounding spaces.
function dropThe(s) {
  if (typeof s !== 'string') return s;
  let t = s;
  while (t[0] === ' ') t = t.slice(1);
  if (t.slice(0, 4).toUpperCase() === 'THE ') { t = t.slice(4); while (t[0] === ' ') t = t.slice(1); }
  return t;
}

// Title must carry the RELEASE NAME ONLY. Strip parenthesised/bracketed groups
// that describe the edition/packaging (and a trailing " - <colour/format>" tail),
// keeping genuine parts of the work's name. What is removed is preserved in
// extra.title_variant so nothing is lost.
const VARIANT_RE = /\b(VINYL|LP|CD|MC|DIGI|DIGIPAK|DIGIPACK|LTD|LIMITED|EXCLUSIVE|INDIE|RSD|SIGNED|PICTURE|DISC|DIE-CUT|GATEFOLD|T-SHIRT|PATCH|BOXSET|BOX|DELUXE|EDITION|REISSUE|BLACK|WHITE|RED|GREEN|BLUE|YELLOW|GOLD|SILVER|CLEAR|ORANGE|PURPLE|PINK|GREY|GRAY|MARBLE|SPLATTER|GLITTER|TRANSPARENT|INKSPOT|GLOW|SLUDGE|OPAQUE|CRYSTAL|SOFTPAK|JEWEL|AMARAY|LIGHT)\b/;
function cleanTitle(s) {
  if (typeof s !== 'string') return { title: s, removed: [] };
  const removed = [];
  let t = s.replace(/\s*[\(\[]([^()\[\]]*)[\)\]]/g, function (m, inner) {
    if (VARIANT_RE.test(inner.toUpperCase())) { removed.push(inner.trim()); return ''; }
    return m;
  });
  t = t.replace(/\s+[-–]\s+([^-–]+)$/, function (m, seg) {
    const words = seg.trim().toUpperCase().split(/[\s,\/&+]+/).filter(Boolean);
    if (words.length && words.every(function (w) { return VARIANT_RE.test(w) || /^[0-9]+$/.test(w); })) { removed.push(seg.trim()); return ''; }
    return m;
  });
  t = t.replace(/\s{2,}/g, ' ').replace(/[\s,;:\-–]+$/, '').trim();
  return { title: t, removed: removed };
}
// Artist and title are always upper-case (client rule).
function up(s) { return typeof s === 'string' ? s.toUpperCase() : s; }

// calculation_group: the model over-infers a budget/mid tier from label names
// ("Back Catalogue", "Strategic Marketing") when the source states no price tier at
// all. Same policy as the other guards (dropThe/cleanTitle): trust the model's "2" or
// "3" ONLY when an explicit budget/mid signal is actually printed in the item notes
// or the email body — otherwise force the default "1".
const MIDBUDGET_RE = /\b(budget|mid[-\s]?price|mid[-\s]?line|nice[-\s]?price|reduced[-\s]?price|low[-\s]?price|super[-\s]?budget)\b/i;
function calcGroup(item, src) {
  const g = String(item.calculation_group == null ? '' : item.calculation_group).trim();
  if (g !== '2' && g !== '3') return '1';
  const text = (item.item_notes || '') + '\n' + ((src && src.body) || '');
  return MIDBUDGET_RE.test(text) ? g : '1';
}

// Label -> catalog / supplier_code routing. Compared on a NORMALISED key
// (upper-case, punctuation and spaces removed) because the label arrives in
// whatever shape the model produces: the prompt writes labels in capitals
// ("WARNER/ATLANTIC"), so the model returns "PIAS RECORDINGS", while this code
// used to compare against the literal 'Pias Recordings'. The compare failed
// silently and those lines landed in the MAIN catalog with supplier_code '149'
// instead of OTHER with a blank supplier code. Never compare label strings raw.
function labelKey(s) { return typeof s === 'string' ? s.toUpperCase().replace(/[^A-Z0-9]/g, '') : ''; }
const LABEL_ROUTING = {
  MATRIXMUSIC:    { catalog: 'other', supplier_code: '54' },
  MATRIX:         { catalog: 'other', supplier_code: '54' },
  PIASRECORDINGS: { catalog: 'other', supplier_code: '1009' },
  PIAS:           { catalog: 'other', supplier_code: '1009' },
  IDIMUSIC:       { catalog: 'other', supplier_code: null },   // code not known yet
  IDI:            { catalog: 'other', supplier_code: null },
};
// Anything else -- including a label the AI could not identify (null) -- is the
// main catalog on the default supplier code.
function routeLabelDefault() { return { catalog: 'main', supplier_code: '149' }; }
function routeLabel(label) {
  const r = LABEL_ROUTING[labelKey(label)];
  return r || routeLabelDefault();
}

// --- matching keys ---------------------------------------------------------
function keyEan(v) {
  const d = String(v === null || v === undefined ? '' : v).replace(/\D/g, '').replace(/^0+/, '');
  return d || '';
}
function keyCat(v) {
  return String(v === null || v === undefined ? '' : v).toUpperCase().replace(/[^A-Z0-9]/g, '');
}
// Returns {line, via} on a confident match, {ambiguous, count} when more than one
// candidate fits (never guess), or null when nothing matches.
function findMatch(pool, used, row) {
  const ean = keyEan(row.ean);
  const cat = keyCat(row.catalogue_no);
  const free = pool.filter(function (c) { return !used.has(c.id); });
  // A candidate carrying a DIFFERENT barcode is a different product, full stop.
  const eanOk = function (c) { const ce = keyEan(c.ean); return !ce || !ean || ce === ean; };

  const tiers = [];
  if (ean) tiers.push(['ean', free.filter(function (c) { return keyEan(c.ean) === ean; })]);
  if (cat) tiers.push(['catalogue_no', free.filter(function (c) { return keyCat(c.catalogue_no) === cat && eanOk(c); })]);

  for (const tier of tiers) {
    if (tier[1].length === 1) return { line: tier[1][0], via: tier[0] };
    if (tier[1].length > 1) return { ambiguous: tier[0], count: tier[1].length };
  }
  return null;
}

// --- small helpers ---------------------------------------------------------
function isBlank(v) { return v === null || v === undefined || v === ''; }
function stripBlank(obj) {
  const out = {};
  for (const k of Object.keys(obj)) if (!isBlank(obj[k])) out[k] = obj[k];
  return out;
}
function appendNote(existing, add) {
  const cur = String(existing === null || existing === undefined ? '' : existing).trim();
  if (!add) return cur || null;
  if (!cur) return add;
  if (cur.indexOf(add) !== -1) return cur;   // already recorded — don't repeat it
  return cur + '\n' + add;
}

// "We are not sure" must NEVER become an exclusion. A "WW ex US" release IS
// sellable in Slovenia; excluding it costs the client real business, while
// keeping it costs one review. Only a definite restriction excludes.
const UNSURE_RE = /\b(UNCLEAR|UNCERTAIN|AMBIGUOUS|POSSIBLY|POTENTIALLY|PRESUMABLY|APPARENTLY|UNKNOWN|UNSPECIFIED|NOT SPECIFIED|NOT CLEAR|CANNOT BE DETERMINED)\b/i;

// Fields worth reporting when a follow-up lands on a line that is already in Hermes.
const WATCHED = ['artist', 'title', 'format', 'unit', 'ean', 'catalogue_no', 'release_date', 'label', 'cop', 'ppd', 'rock_bottom', 'price_original', 'currency', 'calculation_group'];

const MANDATORY = $('MandatoryFields').all().map(function (i) { return i.json.field_name; }).filter(Boolean);

const allLines = $('Catalog Lines (matching)').all().map(function (i) { return i.json; });
const openPool = allLines.filter(function (l) { return !l.sent_at; });   // updatable
const sentPool = allLines.filter(function (l) { return !!l.sent_at; });  // frozen in Hermes
const usedOpen = new Set();
const usedSent = new Set();
const createdEans = new Set();
const createdCatNos = new Set();   // only for items that carry NO barcode — see below

const rows = [];
const inputs = $input.all();
for (let i = 0; i < inputs.length; i++) {
  let result = inputs[i].json;
  result = result.output ?? result.message?.content ?? result.content ?? result;
  if (typeof result === 'string') { const a = result.indexOf('{'), b = result.lastIndexOf('}'); try { result = JSON.parse(a >= 0 && b > a ? result.slice(a, b + 1) : result); } catch (e) { continue; } }
  if (!result || result.is_catalog_relevant === false) continue;

  // One source per run, so fall back to the single item when n8n cannot trace
  // the pairing through the merge/agent nodes.
  let src = {};
  try { src = $('Chunk Source').itemMatching(i).json; }
  catch (e) { try { src = $('Chunk Source').first().json; } catch (e2) {} }
  const stamp = String(src.date || '').slice(0, 10) || new Date().toISOString().slice(0, 10);

  for (const item of (result.items ?? [])) {
    const _t = cleanTitle(dropThe(item.title ?? null));

    // Territory guard — see UNSURE_RE above.
    let excluded = item.excluded === true;
    let exclusionReason = item.exclusion_reason ?? null;
    let reviewNote = null;
    if (excluded && exclusionReason && UNSURE_RE.test(exclusionReason)) {
      excluded = false;
      reviewNote = 'Kept in the catalog: the exclusion reason was not definite ("' + exclusionReason + '"). Please confirm the territory.';
      exclusionReason = null;
    }

    // Prefer a label the SOURCE states per item (e.g. a "Label" column in the
    // canvass) over the sender-resolved one: it is read from the data, not guessed,
    // and it is per-row, so a single generic-Warner canvass no longer lands every
    // line with a blank label for the client to type by hand. Routing (catalog +
    // supplier_code) follows the resolved label.
    const itemLabel = (item.label != null && String(item.label).trim() !== '') ? item.label : (result.label ?? null);
    const routing = routeLabel(itemLabel);
    const fields = {
      status: excluded ? 'excluded' : 'in_progress',
      label: itemLabel,
      catalog: routing.catalog,
      thread_id: src.thread_id ?? null,
      artist: up(dropThe(item.artist ?? null)),
      title: up(_t.title),
      format: item.format ?? null,
      genre: item.genre ?? null,
      unit: item.unit ?? null,
      ean: item.ean ?? null,
      code: toCatalogCode(item.ean),
      catalogue_no: item.catalogue_no ?? null,
      release_date: item.release_date ?? null,
      price_original: item.price ?? null,
      currency: item.currency ?? null,
      cop: item.cop ?? null,
      ppd: (function(a,b){a=a!=null?String(a).replace('.',','):null;b=b!=null?String(b).replace('.',','):null;return a&&b?a+'/'+b:(a||b||null);})(item.ppd_eur, item.rock_bottom),
      rock_bottom: item.rock_bottom ?? null,
      our_price: null,
      calculation_group: calcGroup(item, src),
      supplier_code: routing.supplier_code,
      confidence: item.item_confidence ?? result.overall_confidence ?? null,
      notes: item.item_notes ?? null,
    };
    const newExtra = stripBlank({
      artist_raw: item.artist_raw ?? null,
      title_variant: _t.removed.length ? _t.removed.join(' / ') : null,
      exclusion_reason: exclusionReason,
      review_note: reviewNote,
      needs_review: (result.needs_review || reviewNote) ? true : null,
      source_message_id: src.message_id ?? null,
    });

    let match = findMatch(openPool, usedOpen, fields);
    let ambiguousVia = null;
    if (match && match.ambiguous) { ambiguousVia = match.ambiguous; match = null; }

    // --- already in Hermes: report, don't touch ----------------------------
    if (!match) {
      const frozen = findMatch(sentPool, usedSent, fields);
      if (frozen && frozen.line) {
        const line = frozen.line;
        usedSent.add(line.id);
        const changes = [];
        for (const k of WATCHED) {
          if (isBlank(fields[k])) continue;
          const ov = line[k];
          if (String(isBlank(ov) ? '' : ov) !== String(fields[k])) {
            changes.push(k + ': ' + (isBlank(ov) ? '—' : ov) + ' -> ' + fields[k]);
          }
        }
        // Nothing new (e.g. the same email re-processed) -> no note, no write.
        if (!changes.length) continue;
        const note = '[' + stamp + '] Follow-up arrived after this line was sent to Hermes, so it was NOT applied automatically: ' + changes.join('; ');
        rows.push({ json: {
          action: 'update',
          match_line_id: line.id,
          notes: appendNote(line.notes, note),
          extra: Object.assign({}, line.extra || {}, { late_update: { at: stamp, via: frozen.via, changes: changes } }),
        } });
        continue;
      }
    }

    // --- update an open line -----------------------------------------------
    if (match && match.line) {
      const line = match.line;
      usedOpen.add(line.id);
      const patch = stripBlank(fields);   // only what THIS source actually states
      delete patch.our_price;             // always null here; the client fills it by hand
      delete patch.catalog;               // a manual move between Main/Other must stick

      // Never silently un-approve something a human already signed off.
      let approvedNote = null;
      if (line.status === 'approved') {
        delete patch.status;
        if (excluded) {
          approvedNote = '[' + stamp + '] This source marks the release as excluded (' + (exclusionReason || 'no reason given') + ') but the line is already approved — left approved, please review.';
        }
      }

      const merged = appendNote(line.notes, [fields.notes, reviewNote, approvedNote].filter(Boolean).join(' '));
      if (isBlank(merged)) delete patch.notes; else patch.notes = merged;

      const mergedExtra = Object.assign({}, line.extra || {}, newExtra);
      // Back in the catalog -> drop any stale exclusion reason.
      if (!excluded) mergedExtra.exclusion_reason = null;
      patch.extra = mergedExtra;

      // Recompute against the MERGED line, not just this source: a follow-up that
      // supplies the missing EAN should clear "ean" from missing_fields.
      const mergedRow = Object.assign({}, line, patch);
      patch.missing_fields = MANDATORY.filter(function (f) { return isBlank(mergedRow[f]); });

      rows.push({ json: Object.assign({ action: 'update', match_line_id: line.id }, patch) });
      continue;
    }

    // --- new line ------------------------------------------------------------
    // Same-source de-duplication. One email is ONE source rendered several ways
    // (body + attachment, a table row repeated in running text), so the model can
    // report the same release more than once; the prompt says not to, this makes
    // sure of it. Identifiers only, same cascade as the matching above.
    const ek = keyEan(fields.ean);
    if (ek && createdEans.has(ek)) continue;   // same barcode listed twice in one source
    const ck = keyCat(fields.catalogue_no);
    // A catalogue number is shared by the different SKUs of one release, so it only
    // proves "same item" when NEITHER copy carries a barcode to tell them apart.
    if (!ek && ck && createdCatNos.has(ck)) continue;
    if (ek) createdEans.add(ek);
    if (!ek && ck) createdCatNos.add(ck);

    const row = Object.assign({}, fields);
    row.extra = Object.assign({}, newExtra);
    if (ambiguousVia) {
      row.extra.review_note = appendNote(row.extra.review_note, 'Several open lines matched on ' + ambiguousVia + ' — created a new line instead of guessing which one to update.');
      row.extra.needs_review = true;
    }
    row.notes = appendNote(fields.notes, reviewNote);
    row.missing_fields = MANDATORY.filter(function (f) { return isBlank(row[f]); });
    rows.push({ json: Object.assign({ action: 'create', match_line_id: null }, row) });
  }
}
return rows;

// ---- v13 Build Raw Entry1 logic (testable copy of the n8n code node body) ----
// buildRawEntry(inputs, srcFor) where srcFor(i) returns the matching Chunk Source
// json (the n8n node uses `$("Chunk Source").itemMatching(i)` with a `.first()`
// fallback).
//
// One raw_entries row per SOURCE. The completeness audit — every barcode printed in
// the source must come back as an item — is written INSIDE `extracted` (jsonb), NOT
// as a dedicated top-level column. That is the fix for the v12 insert failure: the
// Supabase node auto-maps its input to real columns, so a top-level key with no
// column (extraction_audit) makes the whole insert fail and the audit row — the only
// trace of the email — is lost. `extracted` always exists, so the insert can never
// fail on it; the Raw Entries page surfaces extracted.extraction_audit as a column.
const BARCODE_RE = /\b\d{12,14}\b/g;

function keyEan(v) {
  const s = String(v === null || v === undefined ? '' : v).replace(/\D/g, '').replace(/^0+/, '');
  return s || null;
}

function buildRawEntry(inputs, srcFor) {
  const bySource = {};
  const order = [];
  for (let i = 0; i < inputs.length; i++) {
    let result = inputs[i].json;
    result = result.output != null ? result.output : (result.message && result.message.content != null ? result.message.content : (result.content != null ? result.content : result));
    if (typeof result === 'string') { const a = result.indexOf('{'), b = result.lastIndexOf('}'); try { result = JSON.parse(a >= 0 && b > a ? result.slice(a, b + 1) : result); } catch (e) {} }

    const src = srcFor(i) || {};
    const id = src.message_id != null ? src.message_id : 'unknown';
    if (!bySource[id]) { bySource[id] = { src: src, items: [], rows: 0, parts: 0, text: '' }; order.push(id); }
    const b = bySource[id];
    b.items = b.items.concat((result && result.items) || []);
    b.rows += Number(src.chunk_rows || 0);
    b.parts += 1;
    b.text += '\n' + (src.body || '') + '\n' + (src.attachments_text || '');
    if (result) {
      if (b.label == null && result.label != null) b.label = result.label;
      if (b.confidence == null && result.overall_confidence != null) b.confidence = result.overall_confidence;
      if (b.relevant == null && result.is_catalog_relevant != null) b.relevant = result.is_catalog_relevant;
      if (b.reason == null && result.relevance_reason != null) b.reason = result.relevance_reason;
      if (result.needs_review) b.needs_review = true;
      if (result.review_reasons) b.review_reasons = (b.review_reasons || []).concat(result.review_reasons);
    }
  }

  return order.map(function (id) {
    const b = bySource[id];
    const bodyFull = b.src.body_full != null ? b.src.body_full : (b.src.body != null ? b.src.body : null);
    const attFull = b.src.attachments_full != null ? b.src.attachments_full : null;
    const full = attFull === null && bodyFull === null ? b.text : [bodyFull || '', attFull || ''].join('\n');

    const returned = {};
    for (const it of b.items) { const k = keyEan(it && it.ean); if (k) returned[k] = true; }
    const printed = [];
    const seen = {};
    const found = full.match(BARCODE_RE) || [];
    for (const raw of found) { const k = keyEan(raw); if (k && !seen[k]) { seen[k] = true; printed.push(raw); } }
    const missing = b.relevant === false ? [] : printed.filter(function (raw) { return !returned[keyEan(raw)]; });

    const audit = missing.length
      ? b.rows + ' rows in the source, ' + b.items.length + ' items returned (' + b.parts + ' AI part(s)) — ' +
        missing.length + ' BARCODE(S) NOT EXTRACTED: ' + missing.join(', ')
      : null;

    return { json: {
      received_at: b.src.date != null ? b.src.date : null,
      sender: b.src.from != null ? b.src.from : null,
      label: b.label != null ? b.label : null,
      subject: b.src.subject != null ? b.src.subject : null,
      source_email_id: b.src.message_id != null ? b.src.message_id : null,
      ean: b.items[0] && b.items[0].ean != null ? b.items[0].ean : null,
      confidence: b.confidence != null ? b.confidence : null,
      status: 'new',
      extracted: {
        extraction_audit: audit,
        result: {
          is_catalog_relevant: b.relevant != null ? b.relevant : null,
          relevance_reason: b.reason != null ? b.reason : null,
          label: b.label != null ? b.label : null,
          needs_review: b.needs_review != null ? b.needs_review : false,
          review_reasons: b.review_reasons != null ? b.review_reasons : [],
          items: b.items,
        },
        ai_parts: b.parts,
        source_rows: b.rows,
        source_body: bodyFull,
        source_attachments: attFull,
      },
    } };
  });
}

const inputs = $input.all();
function srcFor(i) {
  try { return $("Chunk Source").itemMatching(i).json; }
  catch (e) { try { return $("Chunk Source").first().json; } catch (e2) { return {}; } }
}
return buildRawEntry(inputs, srcFor);

// ---- v13 Chunk Source logic (testable copy of the n8n code node body) ----
// Exported as chunkSource(inputs) where inputs = [{ json }, ...]; the n8n node
// wraps the identical body with `const inputs = $input.all();` and `return out;`.

const MAX_ROWS = 12;

// A Markdown table separator row: | --- | :---: | etc. Tolerates a missing outer pipe.
const SEP_RE = /^\s*\|?[\s:|]*-{2,}[\s:|-]*\|?\s*$/;
// What marks a line as a real PRODUCT row: a barcode-length run (12-14 digits) or a
// day-month-year date. Deliberately NOT "any 6+ digit number" — a canvass id or a
// price must not be mistaken for a product. A row with neither is treated as a
// header/caption/continuation, never counted as an item.
const BARCODE_RE = /\d{12,14}/;
const DATE_RE = /\d{1,2}[.\/-]\d{1,2}[.\/-]\d{2,4}/;
const HEADING_RE = /^##\s+Attachment:/;

function isSep(l) { return SEP_RE.test(l); }
function isTableLine(l) { return String(l).trim().charAt(0) === '|'; }
function hasData(l) { return BARCODE_RE.test(l) || DATE_RE.test(l); }

// Words of running prose in a set of lines (excludes the "## Attachment:" heading,
// blanks and separators). Used only to judge whether a blob is "just a table" or
// carries prose that might itself list releases.
function proseWords(lines) {
  let w = 0;
  for (const l of lines) {
    const t = String(l).trim();
    if (!t || HEADING_RE.test(t) || isSep(t)) continue;
    w += t.split(/\s+/).filter(function (x) { return /[A-Za-z]/.test(x); }).length;
  }
  return w;
}

// Parse one contiguous run of "|" lines into { head, rows, hasSep }.
// head  = the title/separator/column-name block that must be repeated in every part.
// rows  = one string per PRODUCT row (a data line plus any non-data continuation
//         lines that follow it), so nothing is ever lost or double-counted.
// LlamaParse commonly emits [title row][--- separator][column header][data rows]:
// the header sits AFTER the separator, so we anchor on the separator when the first
// data-looking line appears before it (a captioned/ dated title row).
function splitTableSeg(lines) {
  let sepIdx = -1;
  for (let i = 0; i < lines.length; i++) { if (isSep(lines[i])) { sepIdx = i; break; } }

  let first = -1;
  for (let i = 0; i < lines.length; i++) {
    if (isSep(lines[i])) continue;
    if (hasData(lines[i])) { first = i; break; }
  }
  // A dated/number-bearing TITLE row before the separator is not a product row:
  // the real rows start after the separator.
  if (sepIdx >= 0 && first >= 0 && first < sepIdx) {
    first = -1;
    for (let i = sepIdx + 1; i < lines.length; i++) {
      if (isSep(lines[i])) continue;
      if (hasData(lines[i])) { first = i; break; }
    }
  }
  if (first < 0) return null;

  const head = lines.slice(0, first);
  let hasSep = false;
  for (const l of head) if (isSep(l)) hasSep = true;

  const rows = [];
  let cur = null;
  for (let i = first; i < lines.length; i++) {
    const l = lines[i];
    if (isSep(l)) continue;
    if (hasData(l)) { if (cur !== null) rows.push(cur); cur = l; }
    else { cur = cur === null ? l : cur + '\n' + l; } // continuation of the current row
  }
  if (cur !== null) rows.push(cur);
  return { head: head, rows: rows, hasSep: hasSep };
}

// Split one Markdown blob (an email body or one attachment) into parts of at most
// MAX_ROWS product rows. Returns { total, confident, prose, parts }.
//   total     = counted product rows across every clean table in the blob.
//   confident = total>0 AND every "|" run we counted looked like a real, separator-
//               delimited table (so `total` can be trusted as an EXACT count).
//   prose     = words of running text outside the tables (may itself list releases).
// A blob that fits in one part is returned whole (only the count is added).
function chunkBlob(text) {
  const lines = String(text || '').split('\n');
  const segs = [];
  for (const l of lines) {
    const type = isTableLine(l) ? 'table' : 'text';
    if (!segs.length || segs[segs.length - 1].type !== type) segs.push({ type: type, lines: [] });
    segs[segs.length - 1].lines.push(l);
  }

  let total = 0;
  let messyTable = false; // a "|" run we could not parse, or a table with no separator
  let prose = 0;
  for (const s of segs) {
    if (s.type === 'table') {
      s.tp = splitTableSeg(s.lines);
      if (s.tp) { total += s.tp.rows.length; if (!s.tp.hasSep) messyTable = true; }
      else { messyTable = true; prose += proseWords(s.lines); }
    } else {
      prose += proseWords(s.lines);
    }
  }
  const confident = total > 0 && !messyTable;

  if (total <= MAX_ROWS) {
    return { total: total, confident: confident, prose: prose, parts: [{ text: String(text || ''), rows: total }] };
  }

  // Long enough to split. Repeat the "## Attachment:" heading and the table head in
  // every part; prose stays with the part it appears in (repeating it would invite
  // the same release to be extracted twice).
  const parts = [];
  let heading = '';
  let cur = [];
  let curRows = 0;
  for (const s of segs) {
    if (s.type === 'text' || !s.tp) {
      for (const l of s.lines) { if (HEADING_RE.test(String(l).trim())) heading = String(l).trim(); cur.push(l); }
      continue;
    }
    for (const l of s.tp.head) cur.push(l);
    for (const row of s.tp.rows) {
      if (curRows >= MAX_ROWS) {
        parts.push({ text: cur.join('\n').trim(), rows: curRows });
        cur = [];
        curRows = 0;
        if (heading) { cur.push(heading); cur.push(''); }
        for (const l of s.tp.head) cur.push(l);
      }
      cur.push(row);
      curRows++;
    }
  }
  if (curRows) parts.push({ text: cur.join('\n').trim(), rows: curRows });
  else if (cur.join('').trim() && parts.length) parts[parts.length - 1].text += '\n' + cur.join('\n').trim();
  return { total: total, confident: confident, prose: prose, parts: parts };
}

// Build the instruction that governs how many items a part must yield.
//   rows       = counted product rows in THIS part (0 when nothing tabular counted).
//   exact      = those rows came from a clean, separator-delimited table, so `rows`
//                is trustworthy as a hard target.
//   proseSource= this part ALSO carries running text that is part of the source (not
//                already-extracted context) and may itself list releases.
// When both a trustworthy table count AND prose are present, the count is asserted as
// a FLOOR for the table plus "extract every release in the text too" — never a hard
// total that could make the model drop a prose-only release. When the count is not
// trustworthy, no number is asserted at all (a wrong number is worse than none); the
// barcode audit in Build Raw Entry1 is the backstop.
function note(index, count, rows, exact, proseSource, bodyIsSource) {
  let core;
  if (rows > 0 && exact && !proseSource) {
    core = 'This part contains exactly ' + rows + ' product rows: return EXACTLY that many items, one per row, in the same order. Never sample, summarise, shorten or stop early — a row you skip is a release the client never gets to sell.';
  } else if (rows > 0 && exact && proseSource) {
    core = 'The table in this part has exactly ' + rows + ' product rows: return an item for EVERY one, one per row, none skipped. The message text above is ALSO part of this source — extract every release it lists in addition (there may be none). Never sample, summarise or stop early.';
  } else {
    core = 'Extract every single release this part contains — one item each, reading top to bottom. Never sample, summarise, shorten or stop early; a release you skip is one the client never gets to sell.';
  }
  if (count === 1) return core;
  return 'PART ' + index + ' OF ' + count + ' of this source. ' + core +
    (bodyIsSource ? '' : ' The message text above is CONTEXT ONLY in this part — the items it lists were already extracted in an earlier part, so do not repeat them here.');
}

function chunkSource(inputs) {
  const out = [];
  for (let i = 0; i < inputs.length; i++) {
    const src = inputs[i].json;
    const body = src.body || '';
    const att = src.attachments_text || '';
    const B = chunkBlob(body);
    const A = chunkBlob(att);
    const total = B.total + A.total;

    const base = Object.assign({}, src, { body_full: body, attachments_full: att });

    // Whole source fits in one AI call. Assert an exact count only when the tables are
    // clean AND there is no substantial prose that might carry its own releases.
    if (total <= MAX_ROWS) {
      const cleanTables = (A.total === 0 || A.confident) && (B.total === 0 || B.confident);
      const proseSource = (A.prose + B.prose) > 40; // running text beyond the table(s)
      const exact = total > 0 && cleanTables;
      out.push({
        json: Object.assign({}, base, {
          chunk_index: 1, chunk_count: 1, chunk_rows: total,
          chunk_note: note(1, 1, total, exact, proseSource, true),
        }),
        pairedItem: { item: i },
      });
      continue;
    }

    // Long source. Which carrier is long decides the shape (mirrors v12): a short body
    // rides on every attachment part as context; a body long enough to split becomes
    // parts of its own and the attachment parts that follow drop it.
    const used = function (p) { return p.rows > 0 || p.text.trim() !== ''; };
    const bParts = B.parts.filter(used);
    const aParts = A.parts.filter(used);
    const bodyIsProse = B.total === 0 && B.prose > 0; // body carries releases only as text
    const bodyProseSource = bodyIsProse && B.prose > 40;

    const parts = [];
    if (B.total > MAX_ROWS) {
      for (const p of bParts) parts.push({ body: p.text, att: '', rows: p.rows, exact: B.confident, proseSource: B.prose > 40, bodySource: true });
      for (const p of aParts) parts.push({ body: '', att: p.text, rows: p.rows, exact: A.confident, proseSource: false, bodySource: false });
    } else if (aParts.length) {
      for (let k = 0; k < aParts.length; k++) {
        const first = k === 0;
        parts.push({
          body: body,
          att: aParts[k].text,
          rows: aParts[k].rows + (first ? B.total : 0),
          exact: A.confident && (!first || B.total === 0 || B.confident),
          proseSource: first && bodyProseSource,
          bodySource: first,
        });
      }
    } else {
      for (const p of bParts) parts.push({ body: p.text, att: att, rows: p.rows, exact: B.confident, proseSource: B.prose > 40, bodySource: true });
    }

    for (let k = 0; k < parts.length; k++) {
      const P = parts[k];
      out.push({
        json: Object.assign({}, base, {
          body: P.body,
          attachments_text: P.att,
          chunk_index: k + 1,
          chunk_count: parts.length,
          chunk_rows: P.rows,
          chunk_note: note(k + 1, parts.length, P.rows, P.exact, P.proseSource, P.bodySource),
        }),
        pairedItem: { item: i },
      });
    }
  }
  return out;
}

const inputs = $input.all();
return chunkSource(inputs);
